import React, { useState } from 'react';
import Login from '../components/Login';
import FrostedContainer from '../components/FrostedContainer';
import Button from '../components/Button';
import './App.css';

function App() {
  const [user, setUser] = useState(null);
  const [showLogin, setShowLogin] = useState(true);

  const handleLogin = (userData) => {
    setUser(userData);
    setShowLogin(false);
  };

  const handleLogout = () => {
    setUser(null);
    setShowLogin(true);
  };

  if (showLogin) {
    return (
      <div className="app">
        <div className="bg"></div>
        <Login onLogin={handleLogin} />
      </div>
    );
  }

  return (
    <div className="app">
      <div className="bg"></div>
      <div className="dashboard">
        <FrostedContainer variant="modal" className="welcome-card">
          <h1>¡Bienvenido, {user?.username}!</h1>
          <p>Has iniciado sesión exitosamente en tu nube personal.</p>
          <div className="dashboard-actions">
            <Button variant="primary" onClick={() => alert('Funcionalidad próximamente')}>
              Mi Unidad
            </Button>
            <Button variant="secondary" onClick={() => alert('Funcionalidad próximamente')}>
              Compartidos
            </Button>
            <Button variant="danger" onClick={handleLogout}>
              Cerrar Sesión
            </Button>
          </div>
        </FrostedContainer>
      </div>
    </div>
  );
}

export default App;
